-- Тестовые данные CafeHelp. Все люди, телефоны и адреса выдуманы.
-- Сгенерировано deploy/vm/tools/gen_seed.py. Применяется к пустой схеме после миграций backend.
BEGIN;
SET search_path = sales, public;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM sales.dish) THEN RAISE EXCEPTION 'База уже содержит блюда - seed не применяется'; END IF; END $$;
-- Смены и заказы за последние 60 дней (день 0 = сегодня, смена открыта)





























































SELECT setval(pg_get_serial_sequence('sales.supplier', 'supplierid'), (SELECT COALESCE(MAX(supplierid), 1) FROM sales.supplier));
SELECT setval(pg_get_serial_sequence('sales.product', 'productid'), (SELECT COALESCE(MAX(productid), 1) FROM sales.product));
SELECT setval(pg_get_serial_sequence('sales.warehouse', 'warehouseid'), (SELECT COALESCE(MAX(warehouseid), 1) FROM sales.warehouse));
SELECT setval(pg_get_serial_sequence('sales.preparation', 'preparationid'), (SELECT COALESCE(MAX(preparationid), 1) FROM sales.preparation));
SELECT setval(pg_get_serial_sequence('sales.dish_category', 'category_id'), (SELECT COALESCE(MAX(category_id), 1) FROM sales.dish_category));
SELECT setval(pg_get_serial_sequence('sales.dish', 'dishid'), (SELECT COALESCE(MAX(dishid), 1) FROM sales.dish));
SELECT setval(pg_get_serial_sequence('sales.dish_set', 'setid'), (SELECT COALESCE(MAX(setid), 1) FROM sales.dish_set));
SELECT setval(pg_get_serial_sequence('sales.person', 'personid'), (SELECT COALESCE(MAX(personid), 1) FROM sales.person));
SELECT setval(pg_get_serial_sequence('sales.client', 'clientid'), (SELECT COALESCE(MAX(clientid), 1) FROM sales.client));
SELECT setval(pg_get_serial_sequence('sales.shift', 'id'), (SELECT COALESCE(MAX(id), 1) FROM sales.shift));
SELECT setval(pg_get_serial_sequence('sales."order"', 'orderid'), (SELECT COALESCE(MAX(orderid), 1) FROM sales."order"));
SELECT setval(pg_get_serial_sequence('sales.orderdish', 'id'), (SELECT COALESCE(MAX(id), 1) FROM sales.orderdish));
SELECT setval(pg_get_serial_sequence('sales.order_consumable', 'id'), (SELECT COALESCE(MAX(id), 1) FROM sales.order_consumable));
SELECT setval(pg_get_serial_sequence('sales.techproduct', 'techproductid'), (SELECT COALESCE(MAX(techproductid), 1) FROM sales.techproduct));
SELECT setval(pg_get_serial_sequence('sales.dish_set_item', 'set_item_id'), (SELECT COALESCE(MAX(set_item_id), 1) FROM sales.dish_set_item));
SELECT setval(pg_get_serial_sequence('sales.productwarehouse', 'productwarehouseid'), (SELECT COALESCE(MAX(productwarehouseid), 1) FROM sales.productwarehouse));
SELECT setval(pg_get_serial_sequence('sales.preparationwarehouse', 'preparationwarehouseid'), (SELECT COALESCE(MAX(preparationwarehouseid), 1) FROM sales.preparationwarehouse));
SELECT setval(pg_get_serial_sequence('sales.user_account', 'id'), (SELECT COALESCE(MAX(id), 1) FROM sales.user_account));
SELECT setval(pg_get_serial_sequence('sales.shiftperson', 'shiftpersonid'), (SELECT COALESCE(MAX(shiftpersonid), 1) FROM sales.shiftperson));
COMMIT;
